CREATE TABLE IF NOT EXISTS emergency_cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, patient_id uuid NOT NULL REFERENCES patients(id) ON DELETE CASCADE, encounter_id uuid REFERENCES encounters(id) ON DELETE SET NULL, acuity text NOT NULL DEFAULT 'urgent', chief_complaint text, triage_level text, status text NOT NULL DEFAULT 'arrived', arrival_at timestamptz NOT NULL DEFAULT now(), disposition text, disposition_at timestamptz, notes jsonb NOT NULL DEFAULT '{}', created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS admissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, patient_id uuid NOT NULL REFERENCES patients(id) ON DELETE CASCADE, encounter_id uuid REFERENCES encounters(id) ON DELETE SET NULL, ward text, bed text, status text NOT NULL DEFAULT 'admitted', admitted_at timestamptz NOT NULL DEFAULT now(), discharged_at timestamptz, discharge_summary text, created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS nursing_assessments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, patient_id uuid NOT NULL REFERENCES patients(id) ON DELETE CASCADE, encounter_id uuid REFERENCES encounters(id) ON DELETE SET NULL, nurse_user_id uuid REFERENCES users(id), assessment_type text NOT NULL DEFAULT 'initial', findings jsonb NOT NULL DEFAULT '{}', pain_score numeric, risk_flags jsonb NOT NULL DEFAULT '[]', status text NOT NULL DEFAULT 'completed', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS surgery_cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, patient_id uuid NOT NULL REFERENCES patients(id) ON DELETE CASCADE, encounter_id uuid REFERENCES encounters(id) ON DELETE SET NULL, procedure_name text NOT NULL, scheduled_at timestamptz, status text NOT NULL DEFAULT 'scheduled', consent_confirmed boolean NOT NULL DEFAULT false, checklist jsonb NOT NULL DEFAULT '{}', surgeon_user_id uuid REFERENCES users(id), anaesthesia_plan text, notes jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS maternity_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, patient_id uuid NOT NULL REFERENCES patients(id) ON DELETE CASCADE, encounter_id uuid REFERENCES encounters(id) ON DELETE SET NULL, pregnancy_id uuid, event_type text NOT NULL, gestational_age_weeks numeric, gravida integer, para integer, maternal_observations jsonb NOT NULL DEFAULT '{}', fetal_observations jsonb NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'active', event_at timestamptz NOT NULL DEFAULT now(), notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS pediatric_assessments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, patient_id uuid NOT NULL REFERENCES patients(id) ON DELETE CASCADE, encounter_id uuid REFERENCES encounters(id) ON DELETE SET NULL, age_months integer, weight_kg numeric, height_cm numeric, muac_mm numeric, temperature numeric, respiratory_rate numeric, spo2 numeric, assessment jsonb NOT NULL DEFAULT '{}', imci_classification jsonb NOT NULL DEFAULT '{}', nutrition_status text, referral_required boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS immunizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, patient_id uuid NOT NULL REFERENCES patients(id) ON DELETE CASCADE, vaccine_code text NOT NULL, vaccine_name text NOT NULL, dose_number text, administered_at timestamptz NOT NULL DEFAULT now(), lot_number text, expiry_date date, route text, site text, vaccinator_user_id uuid REFERENCES users(id), status text NOT NULL DEFAULT 'administered', next_due_at timestamptz, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS chronic_care_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, patient_id uuid NOT NULL REFERENCES patients(id) ON DELETE CASCADE, encounter_id uuid REFERENCES encounters(id) ON DELETE SET NULL, condition_code text NOT NULL, condition_name text NOT NULL, status text NOT NULL DEFAULT 'active', goals jsonb NOT NULL DEFAULT '[]', measures jsonb NOT NULL DEFAULT '{}', medications jsonb NOT NULL DEFAULT '[]', next_review_at timestamptz, risk_level text, care_plan jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS telemedicine_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, patient_id uuid NOT NULL REFERENCES patients(id) ON DELETE CASCADE, appointment_id uuid REFERENCES appointments(id) ON DELETE SET NULL, encounter_id uuid REFERENCES encounters(id) ON DELETE SET NULL, scheduled_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'scheduled', meeting_url text, identity_verified boolean NOT NULL DEFAULT false, consent_confirmed boolean NOT NULL DEFAULT false, started_at timestamptz, ended_at timestamptz, provider_user_id uuid REFERENCES users(id), notes jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS remote_monitoring_readings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, patient_id uuid NOT NULL REFERENCES patients(id) ON DELETE CASCADE, device_id text, metric text NOT NULL, value_numeric numeric, unit text, measured_at timestamptz NOT NULL, source text NOT NULL DEFAULT 'patient', validation_status text NOT NULL DEFAULT 'unvalidated', alert_status text NOT NULL DEFAULT 'none', metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS emergency_cases_org_idx ON emergency_cases(organization_id, status, arrival_at DESC);
CREATE INDEX IF NOT EXISTS admissions_org_idx ON admissions(organization_id, status, admitted_at DESC);
CREATE INDEX IF NOT EXISTS nursing_assessments_patient_idx ON nursing_assessments(patient_id, created_at DESC);
CREATE INDEX IF NOT EXISTS surgery_cases_org_idx ON surgery_cases(organization_id, status, scheduled_at DESC);
CREATE INDEX IF NOT EXISTS maternity_patient_idx ON maternity_records(patient_id, event_at DESC);
CREATE INDEX IF NOT EXISTS pediatric_patient_idx ON pediatric_assessments(patient_id, created_at DESC);
CREATE INDEX IF NOT EXISTS immunizations_patient_idx ON immunizations(patient_id, administered_at DESC);
CREATE INDEX IF NOT EXISTS chronic_patient_idx ON chronic_care_records(patient_id, status, next_review_at);
CREATE INDEX IF NOT EXISTS telemedicine_org_idx ON telemedicine_sessions(organization_id, status, scheduled_at);
CREATE INDEX IF NOT EXISTS remote_monitoring_patient_idx ON remote_monitoring_readings(patient_id, metric, measured_at DESC);
